"""Generate .env.example from config.Settings metadata (single source of truth).

Run after changing config.py:  just env-example
"""

from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from config import Settings

HEADER = """\
# Generated by scripts/gen_env_example.py from config.py -- edit config.py, then regenerate.
# cp .env.example .env   # then fill in machine-specific values
"""


def default_repr(value) -> str:
    if value is None:
        return ""
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)


def main() -> None:
    lines = [HEADER]
    for name, field in Settings.model_fields.items():  # pydantic v2
        env_name = name.upper()
        description = (field.description or "").strip()
        default = field.get_default(call_default_factory=True)
        if description:
            lines.append(f"# {description}")
        lines.append(f"{env_name}={default_repr(default)}")
        lines.append("")

    out = Path(".env.example")
    out.write_text("\n".join(lines).rstrip() + "\n")
    print(f"wrote {out} ({len(Settings.model_fields)} keys)")


if __name__ == "__main__":
    main()
